#!/bin/bash
set -e
echo ""
echo "╔══════════════════════════════════════╗"
echo "║  October Outreach — Plugin (2 of 2)  ║"
echo "╚══════════════════════════════════════╝"

source /root/.oo/creds
PLUGIN_DIR="$WEB_DIR/wp-content/plugins/october-outreach"

echo "Creating plugin files..."
mkdir -p "$PLUGIN_DIR/includes"
mkdir -p "$PLUGIN_DIR/admin/css"
mkdir -p "$PLUGIN_DIR/admin/js"
mkdir -p "$PLUGIN_DIR/admin/views"

echo "" | base64 -d > "$PLUGIN_DIR/october-outreach.php"
echo "" | base64 -d > "$PLUGIN_DIR/includes/class-oo-database.php"
echo "" | base64 -d > "$PLUGIN_DIR/includes/class-oo-license.php"
echo "" | base64 -d > "$PLUGIN_DIR/admin/class-oo-admin.php"
echo "" | base64 -d > "$PLUGIN_DIR/admin/css/admin.css"
echo "" | base64 -d > "$PLUGIN_DIR/admin/js/admin.js"
echo "" | base64 -d > "$PLUGIN_DIR/admin/views/dashboard.php"
echo "" | base64 -d > "$PLUGIN_DIR/admin/views/contacts.php"
echo "" | base64 -d > "$PLUGIN_DIR/admin/views/campaigns.php"
echo "" | base64 -d > "$PLUGIN_DIR/admin/views/press.php"
echo "" | base64 -d > "$PLUGIN_DIR/admin/views/settings.php"

chown -R www-data:www-data "$PLUGIN_DIR"

echo "Activating plugin..."
cd "$WEB_DIR"
sudo -u www-data wp plugin activate october-outreach --allow-root --quiet

echo ""
echo "╔══════════════════════════════════════════════════╗"
echo "║  ALL DONE!                                       ║"
echo "╠══════════════════════════════════════════════════╣"
source /root/.oo/creds
echo "║  WP Admin:  http://195.201.149.223/wp-admin      ║"
echo "║  Username:  $WP_ADMIN_USER                       ║"
echo "║  Password:  $WP_ADMIN_PASS                       ║"
echo "║                                                   ║"
echo "║  License key: OO-MASTER-OCTOBER-UNLIMITED        ║"
echo "║  Go to: Outreach → Settings to enter it          ║"
echo "╚══════════════════════════════════════════════════╝"
